import json

with open('/tmp/axp_chart_data.json') as f:
    chart_data = json.load(f)

price_json = json.dumps(chart_data['price_series'])
yearly_json = json.dumps(chart_data['yearly'])
dd_json = json.dumps(chart_data['drawdown_series'])
div_years_json = json.dumps(chart_data['div_years'])
