html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>American Express (AXP) Historical Stock Performance Report: 1972–2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-annotation@3.0.1/dist/chartjs-plugin-annotation.min.js"></script>
<style>
  :root {{
    --navy: #0A2342;
    --blue: #1A5276;
    --light-blue: #2E86C1;
    --accent: #1ABC9C;
    --gold: #D4AC0D;
    --danger: #C0392B;
    --success: #1E8449;
    --bg: #F4F6F9;
    --card: #FFFFFF;
    --text: #1C2833;
    --muted: #626567;
    --border: #E0E4EA;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ font-family: 'Segoe UI', Arial, sans-serif; background: var(--bg); color: var(--text); font-size: 14px; line-height: 1.6; }}

  .report-header {{
    background: linear-gradient(135deg, var(--navy) 0%, var(--blue) 100%);
    color: white;
    padding: 40px 48px 36px;
  }}
  .report-header .ticker {{ font-size: 13px; letter-spacing: 3px; text-transform: uppercase; opacity: 0.7; margin-bottom: 8px; }}
  .report-header h1 {{ font-size: 28px; font-weight: 700; margin-bottom: 6px; }}
  .report-header .subtitle {{ font-size: 15px; opacity: 0.85; }}
  .report-header .meta {{ display: flex; gap: 32px; margin-top: 24px; font-size: 13px; opacity: 0.75; }}

  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 24px; }}

  section {{ padding: 36px 0 20px; }}

  h2 {{
    font-size: 20px; font-weight: 700; color: var(--navy);
    padding-bottom: 8px; margin-bottom: 20px;
    border-bottom: 3px solid var(--light-blue);
    display: flex; align-items: center; gap: 10px;
  }}
  h2 .sec-num {{ 
    background: var(--navy); color: white; 
    width: 28px; height: 28px; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center;
    font-size: 13px; font-weight: 700; flex-shrink: 0;
  }}

  h3 {{ font-size: 15px; font-weight: 600; color: var(--blue); margin: 18px 0 10px; }}

  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin: 24px 0;
  }}
  .kpi-card {{
    background: var(--card);
    border-radius: 10px;
    padding: 20px 16px;
    border-top: 4px solid var(--light-blue);
    box-shadow: 0 2px 8px rgba(0,0,0,0.07);
  }}
  .kpi-card.highlight {{ border-top-color: var(--accent); }}
  .kpi-card.warning {{ border-top-color: var(--danger); }}
  .kpi-card.gold {{ border-top-color: var(--gold); }}
  .kpi-label {{ font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: var(--muted); margin-bottom: 6px; }}
  .kpi-value {{ font-size: 26px; font-weight: 700; color: var(--navy); }}
  .kpi-sub {{ font-size: 12px; color: var(--muted); margin-top: 4px; }}
  .kpi-value.positive {{ color: var(--success); }}
  .kpi-value.negative {{ color: var(--danger); }}

  .card {{
    background: var(--card);
    border-radius: 10px;
    padding: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.07);
    margin-bottom: 20px;
  }}

  .chart-container {{ position: relative; }}
  .chart-tall {{ height: 380px; }}
  .chart-medium {{ height: 280px; }}
  .chart-short {{ height: 220px; }}

  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  .three-col {{ display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }}

  table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  thead tr {{ background: var(--navy); color: white; }}
  thead th {{ padding: 10px 12px; text-align: right; font-weight: 600; font-size: 12px; letter-spacing: 0.5px; }}
  thead th:first-child {{ text-align: left; }}
  tbody tr {{ border-bottom: 1px solid var(--border); }}
  tbody tr:hover {{ background: #F0F4FA; }}
  tbody td {{ padding: 9px 12px; text-align: right; }}
  tbody td:first-child {{ text-align: left; font-weight: 500; }}
  .pos {{ color: var(--success); font-weight: 600; }}
  .neg {{ color: var(--danger); font-weight: 600; }}
  .neutral {{ color: var(--muted); }}

  .insight-box {{
    background: linear-gradient(135deg, #EBF5FB, #E8F8F5);
    border-left: 4px solid var(--accent);
    border-radius: 6px;
    padding: 14px 16px;
    margin: 14px 0;
    font-size: 13px;
    color: var(--text);
  }}
  .insight-box strong {{ color: var(--navy); }}

  .crisis-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin: 16px 0;
  }}
  .crisis-card {{
    background: #FEF9E7;
    border: 1px solid #F9E79F;
    border-top: 3px solid var(--danger);
    border-radius: 8px;
    padding: 14px 12px;
  }}
  .crisis-name {{ font-size: 12px; font-weight: 700; color: var(--navy); margin-bottom: 8px; }}
  .crisis-dd {{ font-size: 22px; font-weight: 800; color: var(--danger); }}
  .crisis-detail {{ font-size: 11px; color: var(--muted); margin-top: 4px; }}

  .splits-list {{ display: flex; flex-wrap: wrap; gap: 10px; margin: 10px 0; }}
  .split-tag {{
    background: var(--navy); color: white;
    border-radius: 20px; padding: 5px 14px;
    font-size: 12px; font-weight: 600;
  }}

  .toc {{
    background: var(--card);
    border-radius: 10px;
    padding: 20px 24px;
    margin: 24px 0;
    box-shadow: 0 2px 8px rgba(0,0,0,0.07);
  }}
  .toc h3 {{ margin: 0 0 12px; font-size: 14px; color: var(--navy); }}
  .toc ol {{ padding-left: 20px; }}
  .toc li {{ margin: 5px 0; font-size: 13px; color: var(--light-blue); }}
  .toc a {{ color: inherit; text-decoration: none; }}
  .toc a:hover {{ text-decoration: underline; }}

  .note {{ font-size: 12px; color: var(--muted); font-style: italic; margin-top: 8px; }}

  .footer {{
    background: var(--navy); color: rgba(255,255,255,0.6);
    text-align: center; padding: 24px; font-size: 12px; margin-top: 48px;
  }}

  @media (max-width: 900px) {{
    .kpi-grid {{ grid-template-columns: repeat(3, 1fr); }}
    .crisis-grid {{ grid-template-columns: repeat(2, 1fr); }}
    .two-col {{ grid-template-columns: 1fr; }}
    .three-col {{ grid-template-columns: 1fr; }}
  }}
</style>
</head>
<body>

<div class="report-header">
  <div class="container">
    <div class="ticker">NYSE: AXP &nbsp;·&nbsp; Financial Services</div>
    <h1>American Express (AXP)<br>Historical Stock Performance Report</h1>
    <div class="subtitle">Comprehensive Analysis: June 1972 – March 2026 &nbsp;|&nbsp; 53+ Years of Daily Trading Data</div>
    <div class="meta">
      <span>Report Date: April 21, 2026</span>
      <span>Dataset: 13,556 Trading Days</span>
      <span>Source: AXP Daily OHLCV (Split/Dividend Adjusted)</span>
      <span>Audience: Institutional &amp; Long-Term Investors</span>
    </div>
  </div>
</div>

<div class="container">

  <div class="toc">
    <h3>Table of Contents</h3>
    <ol>
      <li><a href="#executive">Executive Overview</a></li>
      <li><a href="#price-trend">Long-Term Price Trend Analysis</a></li>
      <li><a href="#volatility">Volatility &amp; Risk Assessment</a></li>
      <li><a href="#volume">Trading Volume Analysis</a></li>
      <li><a href="#dividends">Dividend History &amp; Stock Splits</a></li>
      <li><a href="#decade">Decade-by-Decade Performance Comparison</a></li>
    </ol>
  </div>

  <!-- ===== SECTION 1: EXECUTIVE OVERVIEW ===== -->
  <section id="executive">
    <h2><span class="sec-num">1</span> Executive Overview</h2>

    <div class="kpi-grid">
      <div class="kpi-card highlight">
        <div class="kpi-label">Cumulative Return</div>
        <div class="kpi-value positive">24,895%</div>
        <div class="kpi-sub">$1.22 → $305.99 (adj.)</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">CAGR (Full Period)</div>
        <div class="kpi-value">10.81%</div>
        <div class="kpi-sub">June 1972 – March 2026</div>
      </div>
      <div class="kpi-card warning">
        <div class="kpi-label">Max Drawdown</div>
        <div class="kpi-value negative">-83.9%</div>
        <div class="kpi-sub">Jul 2007 → Mar 2009</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Annualized Volatility</div>
        <div class="kpi-value">34.69%</div>
        <div class="kpi-sub">Std Dev × √252 (full period)</div>
      </div>
      <div class="kpi-card gold">
        <div class="kpi-label">Total Dividends Paid</div>
        <div class="kpi-value">$34.27</div>
        <div class="kpi-sub">Per share (adjusted), 1977–2026</div>
      </div>
    </div>

    <div class="card">
      <h3>Summary Narrative</h3>
      <p>American Express Company (AXP) has delivered one of the most compelling long-term equity return profiles in the financial services sector. From an adjusted closing price of <strong>$1.22</strong> in June 1972 to <strong>$305.99</strong> in March 2026, the stock generated a <strong>cumulative return of approximately 24,895%</strong> over 53 years — equivalent to a compounded annual growth rate (CAGR) of <strong>10.81%</strong>. This performance significantly exceeds the long-run historical average of broad equity indices, driven by AXP's powerful brand, premium consumer positioning, and resilient business model.</p>
      <br>
      <p>The all-time high closing price of <strong>$384.04</strong> was reached on <strong>December 11, 2025</strong>. Despite this exceptional long-run trajectory, AXP investors experienced severe episodic losses — most notably an <strong>83.9% drawdown</strong> during the 2007–2009 Global Financial Crisis, reflecting the stock's inherent cyclicality as a credit-driven financial services company. The stock also recorded total dividends of <strong>$34.27 per share</strong> (adjusted), providing meaningful income for long-term holders.</p>
      <div class="insight-box">
        <strong>Key Investment Insight:</strong> AXP rewards patient, long-term investors handsomely, but demands tolerance for deep cyclical drawdowns. The post-GFC recovery CAGR of <strong>23.89%</strong> (2009–2026) illustrates the stock's powerful mean-reversion and earnings recovery capabilities once credit cycle headwinds abate.
      </div>
    </div>

    <div class="two-col">
      <div class="card">
        <h3>Performance vs. Benchmark Reference Points</h3>
        <table>
          <thead><tr><th>Sub-Period</th><th>Start Price</th><th>End Price</th><th>CAGR</th></tr></thead>
          <tbody>
            <tr><td>Full Period (1972–2026)</td><td>$1.22</td><td>$303.15</td><td class="pos">10.79%</td></tr>
            <tr><td>1972–1999</td><td>$1.22</td><td>$34.00</td><td class="pos">12.81%</td></tr>
            <tr><td>2000–2009 (Lost Decade)</td><td>$32.25</td><td>$32.39</td><td class="neutral">0.04%</td></tr>
            <tr><td>2010–2026</td><td>$32.48</td><td>$303.15</td><td class="pos">14.81%</td></tr>
            <tr><td>Post-GFC Recovery (2009–2026)</td><td>$7.93</td><td>$303.15</td><td class="pos">23.89%</td></tr>
          </tbody>
        </table>
        <p class="note">Prices are split/dividend-adjusted closing values.</p>
      </div>
      <div class="card">
        <h3>Price Milestones</h3>
        <table>
          <thead><tr><th>Milestone</th><th>Date</th><th>Price (Adj.)</th></tr></thead>
          <tbody>
            <tr><td>Dataset Start</td><td>Jun 1, 1972</td><td>$1.22</td></tr>
            <tr><td>All-Time Low</td><td>Oct 3, 1974</td><td>$0.38</td></tr>
            <tr><td>Crossed $10</td><td>~1996</td><td>$10+</td></tr>
            <tr><td>Pre-GFC Peak</td><td>Jul 19, 2007</td><td>$49.30</td></tr>
            <tr><td>GFC Trough</td><td>Mar 6, 2009</td><td>$7.93</td></tr>
            <tr><td>All-Time High</td><td>Dec 11, 2025</td><td>$384.04</td></tr>
            <tr><td>Latest Close</td><td>Mar 11, 2026</td><td>$305.99</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  </section>

  <!-- ===== SECTION 2: PRICE TREND ANALYSIS ===== -->
  <section id="price-trend">
    <h2><span class="sec-num">2</span> Long-Term Price Trend Analysis</h2>

    <div class="card">
      <h3>53-Year Closing Price History (Log Scale)</h3>
      <div class="chart-container chart-tall">
        <canvas id="priceChart"></canvas>
      </div>
      <p class="note">Data: 503 sampled daily closing prices (split &amp; dividend adjusted). Chart uses logarithmic scale to clearly display multi-decade growth.</p>
    </div>

    <div class="two-col">
      <div class="card">
        <h3>Bull &amp; Bear Market Phases</h3>
        <table>
          <thead><tr><th>Phase</th><th>Period</th><th>Price Change</th></tr></thead>
          <tbody>
            <tr><td>Bear (Oil Crisis)</td><td>1973–1974</td><td class="neg">−74.7%</td></tr>
            <tr><td>Bull (Recovery)</td><td>1975–1986</td><td class="pos">+757%</td></tr>
            <tr><td>Bear (Black Mon.)</td><td>1987</td><td class="neg">−45.7% peak-trough</td></tr>
            <tr><td>Bull (Growth Era)</td><td>1988–1999</td><td class="pos">+1,665%</td></tr>
            <tr><td>Bear (Dot-com/9-11)</td><td>2000–2002</td><td class="neg">−59.1%</td></tr>
            <tr><td>Bull (Mid-2000s)</td><td>2003–2007</td><td class="pos">+184%</td></tr>
            <tr><td>Bear (GFC)</td><td>2007–2009</td><td class="neg">−83.9%</td></tr>
            <tr><td>Bull (Post-GFC)</td><td>2009–2019</td><td class="pos">+1,346%</td></tr>
            <tr><td>Bear (COVID)</td><td>Feb–Mar 2020</td><td class="neg">−49.6%</td></tr>
            <tr><td>Bull (Recovery)</td><td>2020–2025</td><td class="pos">+502%</td></tr>
          </tbody>
        </table>
      </div>
      <div class="card">
        <h3>CAGR by Sub-Period</h3>
        <div class="chart-container chart-medium">
          <canvas id="cagrChart"></canvas>
        </div>
      </div>
    </div>

    <div class="insight-box">
      <strong>Trend Insight:</strong> AXP's price trajectory exhibits clear structural breaks tied to macro credit cycles. The 1990s bull run (+1,665% from 1988–1999, CAGR ≈21.5%) and post-2009 recovery (+1,346% over a decade) are the two standout bull markets. The 2000–2009 "lost decade" saw essentially flat returns despite an intervening bull phase, underscoring concentration risk in financial services during credit crises.
    </div>
  </section>

  <!-- ===== SECTION 3: VOLATILITY & RISK ===== -->
  <section id="volatility">
    <h2><span class="sec-num">3</span> Volatility &amp; Risk Assessment</h2>

    <div class="card">
      <h3>Historical Drawdown Profile</h3>
      <div class="chart-container chart-tall">
        <canvas id="drawdownChart"></canvas>
      </div>
      <p class="note">Drawdown calculated as percentage decline from running all-time high at each date.</p>
    </div>

    <div class="card">
      <h3>Major Market Crisis Impact on AXP</h3>
      <div class="crisis-grid">
        <div class="crisis-card">
          <div class="crisis-name">1973–74 Oil Crisis</div>
          <div class="crisis-dd">−74.7%</div>
