        </div>
        <div class="crisis-card">
          <div class="crisis-name">1987 Black Monday</div>
          <div class="crisis-dd">−45.7%</div>
          <div class="crisis-detail">Peak: $5.11 (Aug 1987)<br>Trough: $2.77<br>Duration: ~5 months</div>
        </div>
        <div class="crisis-card">
          <div class="crisis-name">2001 Dot-com/9-11</div>
          <div class="crisis-dd">−59.1%</div>
          <div class="crisis-detail">Peak: $38.95 (Oct 2000)<br>Trough: $15.94<br>Duration: ~24 months</div>
        </div>
